-- Generated by scripts/duals/sheets_build.py from the owner's score-sheet workbooks. Dual per-opponent placings (sheet points) + team scores. Id-independent; re-runnable.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @m INT, @t INT, @pid INT, @mp INT;
SET @t = (SELECT TOP 1 Id FROM ScoringTemplates WHERE Name LIKE N'Dual Meet%' AND Deleted=0);

-- ===== 2024 Field-Coventry Double Dual =====
SET @m = (SELECT TOP 1 Id FROM Meets WHERE Name=N'2024 Field-Coventry Double Dual' AND CAST(Date AS date)='2024-04-23');
IF @m IS NULL THROW 50040, 'meet missing', 1;
UPDATE Meets SET MeetType=2, ScoringTemplateId=@t WHERE Id=@m;
IF NOT EXISTS (SELECT 1 FROM MeetParticipants mp JOIN Schools s ON s.Id=mp.SchoolId WHERE mp.MeetId=@m AND s.Name=N'Coventry' AND mp.Deleted=0) INSERT INTO MeetParticipants (MeetId, SchoolId, Gender, SortOrder) SELECT @m, Id, NULL, 0 FROM Schools WHERE Name=N'Coventry';
IF NOT EXISTS (SELECT 1 FROM MeetParticipants mp JOIN Schools s ON s.Id=mp.SchoolId WHERE mp.MeetId=@m AND s.Name=N'Field' AND mp.Deleted=0) INSERT INTO MeetParticipants (MeetId, SchoolId, Gender, SortOrder) SELECT @m, Id, NULL, 1 FROM Schools WHERE Name=N'Field';
-- COV Girls High Jump: place 1 Abigail Reinhardt 4' 4
SET @pid = (SELECT TOP 1 p.Id FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Events e ON e.Id=p.EventId WHERE p.MeetId=@m AND a.FirstName=N'Abigail' AND a.LastName=N'Reinhardt' AND e.Gender=2 AND e.Name=N'High Jump');
SET @mp = (SELECT TOP 1 mp.Id FROM MeetParticipants mp JOIN Schools s ON s.Id=mp.SchoolId WHERE mp.MeetId=@m AND s.Name=N'Coventry' AND mp.Deleted=0);
IF @pid IS NOT NULL AND @mp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid AND MeetParticipantId=@mp) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) VALUES (@m, @pid, @mp, 1, 5.0, 5.0);
